#include "../native/session_state.h"
#include <filesystem>
#include <iostream>
#include <limits>
int wmain(int argc,wchar_t** argv){if(argc!=2)return 2;int checks=0;auto check=[&](bool ok,const char* why){++checks;if(!ok){std::cerr<<"FAIL "<<why<<"\n";exit(1);}};
 const std::string vector="123456789";check(localState::crc32((const unsigned char*)vector.data(),vector.size())==0xcbf43926,"CRC matches published check vector");
 sessionState::State state,decoded;state.selected=true;state.basemap=2;state.workspace=2;state.year=-221;state.infoTab=1;state.regionPage=3;state.layers=7;state.routeId=L"beagle_darwin";state.routeFraction=.4321;state.view.zoom=16;state.view.cx=.823;state.view.cy=.212;state.view.latitude=39.9075;state.view.longitude=116.39723;state.view.grid=3;state.view.exact=true;state.view.name=L"北京 · São Paulo";state.view.origin=L"GeoNames 城市参考位置";
 auto bytes=sessionState::encode(state);check(!bytes.empty()&&sessionState::decode(bytes,decoded),"full session roundtrip");check(decoded.selected&&decoded.basemap==2&&decoded.workspace==2&&decoded.year==-221&&decoded.infoTab==1&&decoded.regionPage==3&&decoded.layers==7&&decoded.routeId==state.routeId&&decoded.routeFraction==state.routeFraction,"workspace, layers, year and stable route identity survive");check(decoded.view.name==state.view.name&&decoded.view.origin==state.view.origin&&decoded.view.latitude==state.view.latitude&&decoded.view.longitude==state.view.longitude&&decoded.view.cx==state.view.cx&&decoded.view.grid==3,"Unicode and exact reference coordinates survive");
 for(size_t i=0;i<bytes.size();++i){auto changed=bytes;changed[i]^=0x20;auto old=decoded;check(!sessionState::decode(changed,decoded)&&decoded.view.name==old.view.name&&decoded.year==old.year,"single-byte corruption rejected transactionally");}
 auto crc=[&](std::vector<unsigned char>& b){uint32_t value=localState::crc32(b.data(),b.size()-4);for(int i=0;i<4;++i)b[b.size()-4+i]=(unsigned char)(value>>(i*8));};
 for(auto field:std::vector<std::pair<size_t,uint32_t>>{{8,2},{12,3},{16,0},{20,3},{24,2},{28,4},{32,12},{36,4},{40,8},{92,0xffffffff}}){auto b=bytes;for(int i=0;i<4;++i)b[field.first+i]=(unsigned char)(field.second>>(i*8));crc(b);check(!sessionState::decode(b,decoded),"invalid field rejected even with valid checksum");}
 auto trailing=bytes;trailing.insert(trailing.end()-4,0);crc(trailing);check(!sessionState::decode(trailing,decoded),"unrecognized trailing fields rejected");for(size_t n:{(size_t)0,(size_t)8,bytes.size()-1}){auto b=std::vector<unsigned char>(bytes.begin(),bytes.begin()+n);check(!sessionState::decode(b,decoded),"truncated session rejected");}
 for(double invalid:{0.,129.,std::numeric_limits<double>::infinity()}){auto s=state;s.view.zoom=invalid;check(sessionState::encode(s).empty(),"invalid zoom cannot be persisted");}auto bad=state;bad.view.name=L"injected\nline";check(sessionState::encode(bad).empty(),"embedded line breaks rejected");
 std::filesystem::create_directories(argv[1]);std::wstring file=std::wstring(argv[1])+L"\\session-test.bin";check(sessionState::write(file,state)&&sessionState::read(file,decoded),"session persists to disk");HANDLE locked=CreateFileW(file.c_str(),GENERIC_READ,FILE_SHARE_READ,nullptr,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,nullptr);check(locked!=INVALID_HANDLE_VALUE,"test opens an incompatible replacement lock");auto newer=state;newer.year=1600;check(!sessionState::write(file,newer),"replacement failure is reported");CloseHandle(locked);check(sessionState::read(file,decoded)&&decoded.year==-221,"failed replacement preserves prior valid state");
 check(!sessionState::write(file,bad)&&sessionState::read(file,decoded)&&decoded.year==-221,"invalid candidate cannot overwrite a valid file");check(!sessionState::write(std::wstring(argv[1])+L"\\missing\\session.bin",state),"missing parent fails without creating unrelated folders");
 std::cout<<checks<<" session checks passed\n";return 0;
}
